    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  function pause(): void {
    clock.synchronize();
    commit({ ...current.current, paused: true });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    loadTournamentSnapshot,
    exportSnapshot,
    activate,
    pause,
    resume,
  };
}

